-- Real-role regression: remote Any Barber must be visible without counting as
-- physical waiting. All records and private broadcast invalidations roll back.
begin;
create temp table live_ids(key text primary key,id uuid);
insert into live_ids values('owner','b31f0000-0000-4000-8000-000000000001'),('customer','b31f0000-0000-4000-8000-000000000002'),('staff1','b31f0000-0000-4000-8000-000000000003'),('staff2','b31f0000-0000-4000-8000-000000000004'),('other','b31f0000-0000-4000-8000-000000000005');
insert into auth.users(id,email) select id,key||'-live-fixture@example.invalid' from live_ids;
create function pg_temp.lid(k text) returns uuid language sql stable as $$select id from pg_temp.live_ids where key=k$$;
create function pg_temp.live_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;end;$$;
create function pg_temp.live_denied(statement text) returns void language plpgsql as $$begin begin execute statement;exception when insufficient_privilege then return;end;raise exception 'Unauthorized operation succeeded';end;$$;
do $$begin execute format('grant usage on schema %I to authenticated,anon',pg_my_temp_schema()::regnamespace::text);end;$$;
grant all on live_ids to authenticated;
grant execute on function pg_temp.lid(text),pg_temp.live_assert(boolean,text),pg_temp.live_denied(text) to authenticated,anon;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.lid('owner'))::text,true);
set local role authenticated;
insert into live_ids select 'salon',(public.manager_command('create_salon',jsonb_build_object('name','Live operations fixture','address','Akurana','service_name','Fixture cut','duration_minutes',1,'price_min_minor',100000,'price_max_minor',140000,'opens_at','00:00','closes_at','23:59','weekdays',jsonb_build_array(0,1,2,3,4,5,6)))->>'id')::uuid;
insert into live_ids select 'service',(public.manager_state()->'salons'->0->'services'->0->>'id')::uuid;
insert into live_ids select 'barber1',(public.manager_command('create_barber',jsonb_build_object('salon_id',pg_temp.lid('salon'),'display_name','First fixture barber','specialities','[]'::jsonb,'service_ids',jsonb_build_array(pg_temp.lid('service'))))->>'id')::uuid;
insert into live_ids select 'barber2',(public.manager_command('create_barber',jsonb_build_object('salon_id',pg_temp.lid('salon'),'display_name','Second fixture barber','specialities','[]'::jsonb,'service_ids',jsonb_build_array(pg_temp.lid('service'))))->>'id')::uuid;
reset role;
insert into bookmyturn_private.salon_memberships(salon_id,user_id,role,barber_id) values(pg_temp.lid('salon'),pg_temp.lid('staff1'),'barber',pg_temp.lid('barber1')),(pg_temp.lid('salon'),pg_temp.lid('staff2'),'barber',pg_temp.lid('barber2'));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.lid('customer'))::text,true);
set local role authenticated;
insert into live_ids select 'queue',(public.customer_command('join_queue',jsonb_build_object('salon_id',pg_temp.lid('salon'),'service_id',pg_temp.lid('service'),'request_key',gen_random_uuid()))->>'id')::uuid;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.lid('owner'))::text,true);
select pg_temp.live_assert((public.manager_state()->'salons'->0->>'incoming')::int=1,'Remote join is visible as incoming');
select pg_temp.live_assert((public.manager_state()->'salons'->0->>'waiting')::int=0,'Remote join does not inflate physical waiting');
select pg_temp.live_assert(public.manager_state()->'salons'->0->'queues'->0->>'id'=pg_temp.lid('queue')::text,'Unassigned Any Barber entry appears at salon level');
select pg_temp.live_assert((public.manager_state()->>'unread')::int=1,'New remote join creates a durable unread owner alert');
insert into live_ids select 'alert',(public.manager_state()->'alerts'->0->>'id')::uuid;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.lid('staff1'))::text,true);
select pg_temp.live_assert(public.barber_state(pg_temp.lid('barber1'))->'queues'->0->>'id'=pg_temp.lid('queue')::text,'Eligible employee sees incoming Any Barber intent');
select pg_temp.live_assert((public.manager_state()->>'unread')::int=1,'Eligible employee receives shared queue alert');
select pg_temp.live_denied($q$select public.manager_visit_command(pg_temp.lid('salon'),'check_in',pg_temp.lid('queue'))$q$);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.lid('other'))::text,true);
select pg_temp.live_assert(jsonb_array_length(public.manager_state()->'alerts')=0,'Unrelated account receives no staff alert');
select public.staff_alert_read(pg_temp.lid('alert'));
select pg_temp.live_denied($q$select public.manager_visit_command(pg_temp.lid('salon'),'check_in',pg_temp.lid('queue'))$q$);
select pg_temp.live_denied('select * from bookmyturn_private.staff_alerts');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.lid('owner'))::text,true);
select pg_temp.live_assert((public.manager_state()->>'unread')::int=1,'Another user cannot mark owner activity read');
select public.staff_alert_read(pg_temp.lid('alert'));
select pg_temp.live_assert((public.manager_state()->>'unread')::int=0,'Read state persists for the correct owner');
select public.manager_visit_command(pg_temp.lid('salon'),'check_in',pg_temp.lid('queue'));
select public.manager_visit_command(pg_temp.lid('salon'),'check_in',pg_temp.lid('queue'));
select pg_temp.live_assert((public.manager_state()->'salons'->0->>'incoming')::int=0 and (public.manager_state()->'salons'->0->>'waiting')::int=1,'Check-in moves intent into physical waiting exactly once');
select pg_temp.live_assert(jsonb_array_length(public.manager_state()->'alerts')=2,'Repeated check-in creates one arrival event');
-- Customer cancellation clears the board and produces a new staff update.
select set_config('bookmyturn.staff_action','0',true);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.lid('customer'))::text,true);
select public.customer_command('cancel_queue',jsonb_build_object('id',pg_temp.lid('queue')));
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.lid('owner'))::text,true);
select pg_temp.live_assert(jsonb_array_length(public.manager_state()->'salons'->0->'queues')=0,'Cancellation disappears from the active board');
select pg_temp.live_assert(exists(select 1 from jsonb_array_elements(public.manager_state()->'alerts')a where a->>'title'='Queue visit cancelled' and a->>'read_at' is null),'Cancellation creates an unread staff alert');
-- Same email/account in both apps still produces a new booking notification.
select set_config('bookmyturn.staff_action','0',true);
insert into live_ids select 'self_queue',(public.customer_command('join_queue',jsonb_build_object('salon_id',pg_temp.lid('salon'),'service_id',pg_temp.lid('service'),'request_key',gen_random_uuid()))->>'id')::uuid;
select pg_temp.live_assert(exists(select 1 from jsonb_array_elements(public.manager_state()->'alerts')a where a->>'entity_id'=pg_temp.lid('self_queue')::text and a->>'read_at' is null),'Manager using Customer app still receives a join alert');
-- Any Barber appointment reaches only the actual held barber's employee account.
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.lid('customer'))::text,true);
insert into live_ids select 'appointment',(public.customer_command('request_appointment',jsonb_build_object('salon_id',pg_temp.lid('salon'),'service_id',pg_temp.lid('service'),'starts_at',((now() at time zone 'Asia/Colombo')::date+1+'14:00'::time) at time zone 'Asia/Colombo','request_key',gen_random_uuid()))->>'id')::uuid;
reset role;
insert into live_ids select 'held_user',m.user_id from bookmyturn_private.barber_schedule_blocks bl join bookmyturn_private.salon_memberships m on m.barber_id=bl.barber_id and m.role='barber' where bl.appointment_id=pg_temp.lid('appointment');
insert into live_ids select 'unheld_user',m.user_id from bookmyturn_private.salon_memberships m where m.salon_id=pg_temp.lid('salon') and m.role='barber' and m.user_id<>pg_temp.lid('held_user');
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.lid('held_user'))::text,true);
select pg_temp.live_assert(exists(select 1 from jsonb_array_elements(public.manager_state()->'alerts')a where a->>'entity_id'=pg_temp.lid('appointment')::text),'Held barber receives appointment alert');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.lid('unheld_user'))::text,true);
select pg_temp.live_assert(not exists(select 1 from jsonb_array_elements(public.manager_state()->'alerts')a where a->>'entity_id'=pg_temp.lid('appointment')::text),'Other employee does not receive a different chair appointment');
do $$declare safe boolean;begin if to_regclass('realtime.messages') is not null then execute $q$select not exists(select 1 from realtime.messages where topic like 'staff:%' and topic<>'staff:'||auth.uid())$q$ into safe;perform pg_temp.live_assert(safe,'Private realtime topics are scoped to the signed-in recipient');end if;end;$$;
reset role;
update bookmyturn_private.salon_memberships set is_active=false where user_id=pg_temp.lid('held_user');
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.lid('held_user'))::text,true);
set local role authenticated;
select pg_temp.live_assert(jsonb_array_length(public.manager_state()->'alerts')=0,'Deactivation immediately hides staff activity');
reset role;
select 'PASS: remote queue visibility, physical counts, durable alerts, self-booking, read state and staff isolation' result;
rollback;
